/* @lc app=leetcode id=1703 lang=kotlin */
class Solution { fun minMoves(nums: IntArray, k: Int): Int = nums.indices.filter { nums[it] == 1 }.let { ones -> LongArray(ones.size + 1).also { pref -> ones.indices.forEach { i -> pref[i + 1] = pref[i] + ones[i] } }.let { pref -> (k / 2).let { m -> (k - 1 - m).let { r -> (m.toLong() * (m + 1) / 2 + r.toLong() * (r + 1) / 2).let { offset -> (0..ones.size - k).minOf { i -> (i + m).let { mid -> (pref[mid] - pref[i]).let { leftSum -> (pref[i + k] - pref[mid + 1]).let { rightSum -> rightSum - leftSum - ones[mid].toLong() * (r - m) - offset } } } }.toInt() } } } } }